import React, { useState, useEffect } from 'react';
import { Plus, Package, Building2, ArrowUpDown, FileText, Calendar, Search, Edit, Trash2, Download } from 'lucide-react';

// Predefined items from your Excel file (first 50 items as example)
const predefinedItems = [
  { id: 1, name: 'Basmathi rice', defaultPrice: 450 },
  { id: 2, name: 'White rice', defaultPrice: 390 },
  { id: 3, name: 'Puttana', defaultPrice: 2 },
  { id: 4, name: 'Ajini moto', defaultPrice: 7 },
  { id: 5, name: 'Tarbooj', defaultPrice: 5 },
  { id: 6, name: 'Anasapuvu', defaultPrice: 1 },
  { id: 7, name: 'Lavang', defaultPrice: 1 },
  { id: 8, name: 'Dalchini', defaultPrice: 5 },
  { id: 9, name: 'Chena dall', defaultPrice: 5 },
  { id: 10, name: 'Jeera', defaultPrice: 7 },
  { id: 11, name: 'Tilli', defaultPrice: 5 },
  { id: 12, name: 'Dhaniyalu', defaultPrice: 8 },
  { id: 13, name: 'Palli', defaultPrice: 15 },
  { id: 14, name: 'Salt', defaultPrice: 50 },
  { id: 15, name: 'Mota salt', defaultPrice: 50 },
  { id: 16, name: 'Copra black', defaultPrice: 10 },
  { id: 17, name: 'Sweet corn', defaultPrice: 10 },
  { id: 18, name: 'Milk maid 400g', defaultPrice: 25 },
  { id: 19, name: 'Coconut milk', defaultPrice: 12 },
  { id: 20, name: 'Vijaya ghee', defaultPrice: 24 },
  // Add more items as needed...
];

const EnhancedProcurementModule = () => {
  const [activeTab, setActiveTab] = useState('stock-input');

  // Stock Input State
  const [stockEntries, setStockEntries] = useState([]);
  const [currentMonth, setCurrentMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM format

  // Stock Distribution State
  const [distributions, setDistributions] = useState([]);

  // Departments State
  const [departments, setDepartments] = useState([
    { id: 1, name: 'South Indian', color: '#10B981', active: true },
    { id: 2, name: 'Biryani', color: '#3B82F6', active: true },
    { id: 3, name: 'Chinese', color: '#EF4444', active: true },
    { id: 4, name: 'Indian', color: '#F59E0B', active: true },
    { id: 5, name: 'Tandoori', color: '#8B5CF6', active: true },
    { id: 6, name: 'Pantry', color: '#06B6D4', active: true },
    { id: 7, name: 'F&B', color: '#EC4899', active: true }
  ]);

  // Forms State
  const [showStockForm, setShowStockForm] = useState(false);
  const [showDistributionForm, setShowDistributionForm] = useState(false);
  const [showDepartmentForm, setShowDepartmentForm] = useState(false);

  // Report State
  const [reportDate, setReportDate] = useState(new Date().toISOString().split('T')[0]);
  const [reportDepartment, setReportDepartment] = useState('');

  const tabs = [
    { id: 'stock-input', label: 'Stock Input', icon: Package },
    { id: 'distribution', label: 'Stock Distribution', icon: ArrowUpDown },
    { id: 'departments', label: 'Departments', icon: Building2 },
    { id: 'reports', label: 'Reports', icon: FileText }
  ];

  // Calculate Net Units (current month entry + previous month availability)
  const calculateNetUnits = (itemId, currentUnits) => {
    // For demo, assume some previous stock exists
    const previousStock = stockEntries
      .filter(entry => entry.itemId === itemId && entry.month < currentMonth)
      .reduce((total, entry) => total + (entry.netUnits || 0), 0);

    // Subtract distributed amounts
    const distributedUnits = distributions
      .filter(dist => dist.itemId === itemId)
      .reduce((total, dist) => total + dist.units, 0);

    return currentUnits + (previousStock - distributedUnits);
  };

  // Stock Input Tab Component
  const StockInputTab = () => {
    const [searchTerm, setSearchTerm] = useState('');

    const currentMonthEntries = stockEntries.filter(entry => entry.month === currentMonth);

    const StockEntryForm = ({ onSave, onCancel }) => {
      const [formData, setFormData] = useState({
        itemId: '',
        itemName: '',
        units: '',
        unitType: 'Kgs',
        price: '',
        month: currentMonth
      });

      const handleItemSelect = (e) => {
        const selectedItem = predefinedItems.find(item => item.id.toString() === e.target.value);
        if (selectedItem) {
          setFormData({
            ...formData,
            itemId: selectedItem.id,
            itemName: selectedItem.name,
            price: selectedItem.defaultPrice
          });
        }
      };

      const handleSubmit = (e) => {
        e.preventDefault();
        const netUnits = calculateNetUnits(parseInt(formData.itemId), parseFloat(formData.units));

        const newEntry = {
          id: Date.now(),
          ...formData,
          itemId: parseInt(formData.itemId),
          units: parseFloat(formData.units),
          netUnits: netUnits,
          price: parseFloat(formData.price),
          totalValue: parseFloat(formData.units) * parseFloat(formData.price)
        };

        setStockEntries([...stockEntries, newEntry]);
        onSave();
      };

      return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <h3 className="text-lg font-semibold mb-4">Add Stock Entry</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Month *</label>
                <input
                  type="month"
                  value={formData.month}
                  onChange={(e) => setFormData({...formData, month: e.target.value})}
                  className="w-full border border-gray-300 rounded-md px-3 py-2"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Item *</label>
                <select
                  value={formData.itemId}
                  onChange={handleItemSelect}
                  className="w-full border border-gray-300 rounded-md px-3 py-2"
                  required
                >
                  <option value="">Select Item</option>
                  {predefinedItems.map(item => (
                    <option key={item.id} value={item.id}>{item.name}</option>
                  ))}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Units *</label>
                  <input
                    type="number"
                    value={formData.units}
                    onChange={(e) => setFormData({...formData, units: e.target.value})}
                    className="w-full border border-gray-300 rounded-md px-3 py-2"
                    min="0"
                    step="0.1"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Unit Type *</label>
                  <select
                    value={formData.unitType}
                    onChange={(e) => setFormData({...formData, unitType: e.target.value})}
                    className="w-full border border-gray-300 rounded-md px-3 py-2"
                  >
                    <option value="Kgs">Kgs</option>
                    <option value="Liters">Liters</option>
                    <option value="Number">Number</option>
                    <option value="Packets">Packets</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Price per Unit (₹) *</label>
                <input
                  type="number"
                  value={formData.price}
                  onChange={(e) => setFormData({...formData, price: e.target.value})}
                  className="w-full border border-gray-300 rounded-md px-3 py-2"
                  min="0"
                  step="0.01"
                  required
                />
              </div>
              <div className="flex justify-end space-x-3 pt-4">
                <button type="button" onClick={onCancel} className="px-4 py-2 text-gray-700 border border-gray-300 rounded-md hover:bg-gray-50">Cancel</button>
                <button type="submit" className="px-4 py-2 bg-blue-500 text-white rounded-md hover:bg-blue-600">Add Entry</button>
              </div>
            </form>
          </div>
        </div>
      );
    };

    return (
      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <div>
            <h3 className="text-lg font-medium text-gray-900">Monthly Stock Input</h3>
            <p className="text-sm text-gray-500">Current Month: {new Date(currentMonth + '-01').toLocaleDateString('en-US', { year: 'numeric', month: 'long' })}</p>
          </div>
          <div className="flex gap-2">
            <input
              type="month"
              value={currentMonth}
              onChange={(e) => setCurrentMonth(e.target.value)}
              className="border border-gray-300 rounded-md px-3 py-2"
            />
            <button
              onClick={() => setShowStockForm(true)}
              className="bg-blue-500 hover:bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2"
            >
              <Plus size={16} />
              Add Stock
            </button>
          </div>
        </div>

        {/* Stock Entries Table */}
        <div className="bg-white shadow overflow-hidden sm:rounded-lg">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Item Name</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Units</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Net Units</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Price/Unit</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Total Value</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {currentMonthEntries.map(entry => (
                <tr key={entry.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm font-medium text-gray-900">{entry.itemName}</div>
                    <div className="text-sm text-gray-500">{entry.month}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                    {entry.units} {entry.unitType}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className="text-sm font-medium text-green-600">
                      {entry.netUnits} {entry.unitType}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                    ₹{entry.price}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                    ₹{entry.totalValue.toFixed(2)}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                    <button className="text-blue-600 hover:text-blue-900 mr-2">
                      <Edit size={16} />
                    </button>
                    <button className="text-red-600 hover:text-red-900">
                      <Trash2 size={16} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {showStockForm && (
          <StockEntryForm
            onSave={() => setShowStockForm(false)}
            onCancel={() => setShowStockForm(false)}
          />
        )}
      </div>
    );
  };

  // Stock Distribution Tab Component
  const DistributionTab = () => {
    const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);

    const DistributionForm = ({ onSave, onCancel }) => {
      const [formData, setFormData] = useState({
        date: new Date().toISOString().split('T')[0],
        itemId: '',
        itemName: '',
        departmentId: '',
        departmentName: '',
        units: '',
        unitType: 'Kgs',
        pricePerUnit: 0,
        totalCost: 0
      });

      const handleItemSelect = (e) => {
        const selectedItemId = e.target.value;
        const stockEntry = stockEntries.find(entry => entry.itemId.toString() === selectedItemId);

        if (stockEntry) {
          setFormData({
            ...formData,
            itemId: selectedItemId,
            itemName: stockEntry.itemName,
            unitType: stockEntry.unitType,
            pricePerUnit: stockEntry.price
          });
        }
      };

      const handleDepartmentSelect = (e) => {
        const selectedDept = departments.find(dept => dept.id.toString() === e.target.value);
        if (selectedDept) {
          setFormData({
            ...formData,
            departmentId: selectedDept.id,
            departmentName: selectedDept.name
          });
        }
      };

      const handleUnitsChange = (e) => {
        const units = parseFloat(e.target.value) || 0;
        const totalCost = units * formData.pricePerUnit;
        setFormData({
          ...formData,
          units: e.target.value,
          totalCost: totalCost
        });
      };

      const handleSubmit = (e) => {
        e.preventDefault();
        const newDistribution = {
          id: Date.now(),
          ...formData,
          itemId: parseInt(formData.itemId),
          departmentId: parseInt(formData.departmentId),
          units: parseFloat(formData.units)
        };

        setDistributions([...distributions, newDistribution]);
        onSave();
      };

      return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <h3 className="text-lg font-semibold mb-4">New Distribution</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Date *</label>
                <input
                  type="date"
                  value={formData.date}
                  onChange={(e) => setFormData({...formData, date: e.target.value})}
                  className="w-full border border-gray-300 rounded-md px-3 py-2"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Stock Item *</label>
                <select
                  value={formData.itemId}
                  onChange={handleItemSelect}
                  className="w-full border border-gray-300 rounded-md px-3 py-2"
                  required
                >
                  <option value="">Select Stock Item</option>
                  {stockEntries.map(entry => (
                    <option key={entry.id} value={entry.itemId}>
                      {entry.itemName} (Available: {entry.netUnits} {entry.unitType})
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Department *</label>
                <select
                  value={formData.departmentId}
                  onChange={handleDepartmentSelect}
                  className="w-full border border-gray-300 rounded-md px-3 py-2"
                  required
                >
                  <option value="">Select Department</option>
                  {departments.filter(dept => dept.active).map(dept => (
                    <option key={dept.id} value={dept.id}>{dept.name}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Units to Distribute * {formData.unitType && `(${formData.unitType})`}
                </label>
                <input
                  type="number"
                  value={formData.units}
                  onChange={handleUnitsChange}
                  className="w-full border border-gray-300 rounded-md px-3 py-2"
                  min="0"
                  step="0.1"
                  required
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Price per Unit</label>
                  <input
                    type="number"
                    value={formData.pricePerUnit}
                    readOnly
                    className="w-full border border-gray-300 rounded-md px-3 py-2 bg-gray-50"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Total Cost</label>
                  <input
                    type="number"
                    value={formData.totalCost.toFixed(2)}
                    readOnly
                    className="w-full border border-gray-300 rounded-md px-3 py-2 bg-gray-50"
                  />
                </div>
              </div>
              <div className="flex justify-end space-x-3 pt-4">
                <button type="button" onClick={onCancel} className="px-4 py-2 text-gray-700 border border-gray-300 rounded-md hover:bg-gray-50">Cancel</button>
                <button type="submit" className="px-4 py-2 bg-green-500 text-white rounded-md hover:bg-green-600">Distribute</button>
              </div>
            </form>
          </div>
        </div>
      );
    };

    const dailyDistributions = distributions.filter(dist => dist.date === selectedDate);

    return (
      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <h3 className="text-lg font-medium text-gray-900">Stock Distribution</h3>
          <div className="flex gap-2">
            <input
              type="date"
              value={selectedDate}
              onChange={(e) => setSelectedDate(e.target.value)}
              className="border border-gray-300 rounded-md px-3 py-2"
            />
            <button
              onClick={() => setShowDistributionForm(true)}
              className="bg-green-500 hover:bg-green-600 text-white px-4 py-2 rounded-lg flex items-center gap-2"
            >
              <ArrowUpDown size={16} />
              New Distribution
            </button>
          </div>
        </div>

        {/* Distributions Table */}
        <div className="bg-white shadow overflow-hidden sm:rounded-lg">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Date</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Item</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Department</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Units</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Rate</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Total Cost</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {dailyDistributions.map(dist => {
                const dept = departments.find(d => d.id === dist.departmentId);
                return (
                  <tr key={dist.id} className="hover:bg-gray-50">
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {new Date(dist.date).toLocaleDateString()}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                      {dist.itemName}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center">
                        <div className="w-3 h-3 rounded-full mr-2" style={{ backgroundColor: dept?.color }}></div>
                        <span className="text-sm text-gray-900">{dist.departmentName}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {dist.units} {dist.unitType}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      ₹{dist.pricePerUnit}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                      ₹{dist.totalCost.toFixed(2)}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          {dailyDistributions.length === 0 && (
            <div className="text-center py-8 text-gray-500">
              No distributions for selected date
            </div>
          )}
        </div>

        {showDistributionForm && (
          <DistributionForm
            onSave={() => setShowDistributionForm(false)}
            onCancel={() => setShowDistributionForm(false)}
          />
        )}
      </div>
    );
  };

  // Departments Tab Component
  const DepartmentsTab = () => {
    const DepartmentForm = ({ onSave, onCancel }) => {
      const [formData, setFormData] = useState({
        name: '',
        color: '#3B82F6',
        active: true
      });

      const colorOptions = [
        '#3B82F6', '#EF4444', '#10B981', '#F59E0B',
        '#8B5CF6', '#06B6D4', '#EC4899', '#F97316'
      ];

      const handleSubmit = (e) => {
        e.preventDefault();
        const newDepartment = {
          id: Date.now(),
          ...formData
        };
        setDepartments([...departments, newDepartment]);
        onSave();
      };

      return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <h3 className="text-lg font-semibold mb-4">Add New Department</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Department Name *</label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) => setFormData({...formData, name: e.target.value})}
                  className="w-full border border-gray-300 rounded-md px-3 py-2"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Color</label>
                <div className="flex space-x-2">
                  {colorOptions.map(color => (
                    <button
                      key={color}
                      type="button"
                      onClick={() => setFormData({...formData, color})}
                      className={`w-8 h-8 rounded-full border-2 ${
                        formData.color === color ? 'border-gray-800' : 'border-gray-300'
                      }`}
                      style={{ backgroundColor: color }}
                    />
                  ))}
                </div>
              </div>
              <div className="flex items-center">
                <input
                  type="checkbox"
                  checked={formData.active}
                  onChange={(e) => setFormData({...formData, active: e.target.checked})}
                  className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
                />
                <label className="ml-2 block text-sm text-gray-900">
                  Active Department
                </label>
              </div>
              <div className="flex justify-end space-x-3 pt-4">
                <button type="button" onClick={onCancel} className="px-4 py-2 text-gray-700 border border-gray-300 rounded-md hover:bg-gray-50">Cancel</button>
                <button type="submit" className="px-4 py-2 bg-blue-500 text-white rounded-md hover:bg-blue-600">Add Department</button>
              </div>
            </form>
          </div>
        </div>
      );
    };

    return (
      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <h3 className="text-lg font-medium text-gray-900">Kitchen Departments</h3>
          <button
            onClick={() => setShowDepartmentForm(true)}
            className="bg-blue-500 hover:bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2"
          >
            <Plus size={16} />
            Add Department
          </button>
        </div>

        {/* Departments Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {departments.map(department => (
            <div key={department.id} className="bg-white rounded-lg shadow p-6 hover:shadow-md transition-shadow">
              <div className="flex items-center justify-between">
                <div className="flex items-center">
                  <div
                    className="w-12 h-12 rounded-lg flex items-center justify-center text-white mr-4"
                    style={{ backgroundColor: department.color }}
                  >
                    <Building2 size={24} />
                  </div>
                  <div>
                    <h4 className="text-lg font-semibold text-gray-900">{department.name}</h4>
                    <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                      department.active ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                    }`}>
                      {department.active ? 'Active' : 'Inactive'}
                    </span>
                  </div>
                </div>
                <button className="text-gray-400 hover:text-gray-600">
                  <Edit size={16} />
                </button>
              </div>
            </div>
          ))}
        </div>

        {showDepartmentForm && (
          <DepartmentForm
            onSave={() => setShowDepartmentForm(false)}
            onCancel={() => setShowDepartmentForm(false)}
          />
        )}
      </div>
    );
  };

  // Reports Tab Component
  const ReportsTab = () => {
    const filteredDistributions = distributions.filter(dist => {
      const matchesDate = dist.date === reportDate;
      const matchesDepartment = reportDepartment === '' || dist.departmentId.toString() === reportDepartment;
      return matchesDate && matchesDepartment;
    });

    const totalCost = filteredDistributions.reduce((total, dist) => total + dist.totalCost, 0);

    const exportToCSV = () => {
      const headers = ['Date', 'Stock Item', 'Department', 'Units', 'Rate', 'Total Cost'];
      const csvData = filteredDistributions.map(dist => [
        dist.date,
        dist.itemName,
        dist.departmentName,
        `${dist.units} ${dist.unitType}`,
        `₹${dist.pricePerUnit}`,
        `₹${dist.totalCost.toFixed(2)}`
      ]);

      const csvContent = [headers, ...csvData]
        .map(row => row.join(','))
        .join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `distribution-report-${reportDate}.csv`;
      link.click();
    };

    return (
      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <h3 className="text-lg font-medium text-gray-900">Distribution Reports</h3>
          <button
            onClick={exportToCSV}
            disabled={filteredDistributions.length === 0}
            className="bg-green-500 hover:bg-green-600 disabled:bg-gray-400 text-white px-4 py-2 rounded-lg flex items-center gap-2"
          >
            <Download size={16} />
            Export CSV
          </button>
        </div>

        {/* Filters */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Select Date</label>
            <input
              type="date"
              value={reportDate}
              onChange={(e) => setReportDate(e.target.value)}
              className="w-full border border-gray-300 rounded-md px-3 py-2"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Select Department</label>
            <select
              value={reportDepartment}
              onChange={(e) => setReportDepartment(e.target.value)}
              className="w-full border border-gray-300 rounded-md px-3 py-2"
            >
              <option value="">All Departments</option>
              {departments.map(dept => (
                <option key={dept.id} value={dept.id}>{dept.name}</option>
              ))}
            </select>
          </div>
        </div>

        {/* Summary Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="bg-white rounded-lg shadow p-4">
            <div className="text-sm font-medium text-gray-600">Total Items Distributed</div>
            <div className="text-2xl font-bold text-blue-600">{filteredDistributions.length}</div>
          </div>
          <div className="bg-white rounded-lg shadow p-4">
            <div className="text-sm font-medium text-gray-600">Total Cost</div>
            <div className="text-2xl font-bold text-green-600">₹{totalCost.toFixed(2)}</div>
          </div>
          <div className="bg-white rounded-lg shadow p-4">
            <div className="text-sm font-medium text-gray-600">Departments Involved</div>
            <div className="text-2xl font-bold text-orange-600">
              {new Set(filteredDistributions.map(d => d.departmentId)).size}
            </div>
          </div>
        </div>

        {/* Report Table */}
        <div className="bg-white shadow overflow-hidden sm:rounded-lg">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Stock Item</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Department</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Units</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Rate</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Total Cost</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {filteredDistributions.map(dist => {
                const dept = departments.find(d => d.id === dist.departmentId);
                return (
                  <tr key={dist.id} className="hover:bg-gray-50">
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                      {dist.itemName}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center">
                        <div className="w-3 h-3 rounded-full mr-2" style={{ backgroundColor: dept?.color }}></div>
                        <span className="text-sm text-gray-900">{dist.departmentName}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {dist.units} {dist.unitType}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      ₹{dist.pricePerUnit}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                      ₹{dist.totalCost.toFixed(2)}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          {filteredDistributions.length === 0 && (
            <div className="text-center py-8 text-gray-500">
              No distributions found for the selected criteria
            </div>
          )}
        </div>
      </div>
    );
  };

  const renderActiveTab = () => {
    switch (activeTab) {
      case 'stock-input':
        return <StockInputTab />;
      case 'distribution':
        return <DistributionTab />;
      case 'departments':
        return <DepartmentsTab />;
      case 'reports':
        return <ReportsTab />;
      default:
        return <StockInputTab />;
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-900">Enhanced Procurement Management</h2>
      </div>

      {/* Tab Navigation */}
      <div className="border-b border-gray-200">
        <nav className="-mb-px flex space-x-8">
          {tabs.map(tab => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center py-2 px-1 border-b-2 font-medium text-sm ${
                  activeTab === tab.id
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                <Icon size={16} className="mr-2" />
                {tab.label}
              </button>
            );
          })}
        </nav>
      </div>

      {/* Active Tab Content */}
      {renderActiveTab()}
    </div>
  );
};

export default EnhancedProcurementModule;
